<script setup>import {Head,Link,router} from '@inertiajs/vue3';defineProps({notices:Object,reports:Array});</script>
<template><Head title="Study Updates"/><h1>Study Updates</h1><p>Question corrections and replies to your reports.</p><p v-if="!notices.data.length" class="notice">You're up to date.</p>
<article v-for="n in notices.data" :key="n.id" class="panel"><p class="eyebrow">{{n.read_at?'Read':'New'}}</p><h2>{{n.title}}</h2><p class="pre">{{n.message}}</p><div class="row"><Link :href="'/library?search='+encodeURIComponent(n.question_id)">View current question</Link><button v-if="!n.read_at" @click="router.post('/updates/'+n.id+'/read',{}, {preserveScroll:true})">Mark read</button></div></article>
<div class="row"><Link v-if="notices.prev_page_url" :href="notices.prev_page_url">Previous</Link><Link v-if="notices.next_page_url" :href="notices.next_page_url">Next</Link></div>
<section class="panel"><h2>Your recent reports</h2><p v-if="!reports.length">Use “Something seems off” beside an explanation to send feedback.</p><details v-for="r in reports" :key="r.id"><summary>{{r.question_id}} · {{r.category}} · {{r.status}}</summary><p>{{r.details}}</p><p v-if="r.resolution">{{r.resolution}}</p><p v-else>Awaiting review.</p></details></section></template>
